        expect(commit.mock.calls[0][0]).toMatchObject({ files: [{ content: 'two', path: 'design/F-1-root.md' }], message: 'Update root' })
        expect(onPendingChange).toHaveBeenCalledTimes(4)
        vi.useRealTimers()

